create or replace function private.nutridex_has_access() returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is not null and not exists(select 1 from private.nutridex_user_access x join auth.users u on lower(u.email)=x.email where u.id=auth.uid() and (x.blocked or x.archived)) and not exists(select 1 from public.billing_accounts a where a.owner_id=auth.uid() and a.blocked) and (private.nutridex_is_admin() or exists(select 1 from private.nutridex_user_access x join auth.users u on lower(u.email)=x.email where u.id=auth.uid() and x.trial_until>now() and u.email_confirmed_at is not null) or exists(select 1 from public.billing_accounts a join public.billing_subscriptions s using(stripe_customer_id) where a.owner_id=auth.uid() and not a.blocked and s.status='active' and s.paid_until>now())); $$;
